// Hiwonder's Ackermann steering chassis as it is sold: the two black plates with the steering servo and the two
// motors, on the four wheels it comes with, the front pair steered and the rear pair driven. What a robot carries
// stands on its upper deck.
Robot ackermann_chassis {
    intent "Hiwonder Ackermann steering chassis as it is sold"

    Ackermann chassis(ref = "hiwonder_ackermann_chassis")

    // The kit's two motors, each on its bracket at a rear wheel.
    Motor motor_left(ref = "hiwonder_520_gearmotor_90_12v", glue = (-0.08607209, 0.06030475, 0.01400358, 0, 1, 0))
    Motor motor_right(ref = "hiwonder_520_gearmotor_90_12v", glue = (-0.08607209, -0.06026475, 0.01400358, 0, -1, 0))

    Standard wheel_front_left(ref = "hiwonder_ackermann_chassis_wheel", glue = (0.0856, 0.0845, 0.014, 0, 1, 0))
    Standard wheel_front_right(ref = "hiwonder_ackermann_chassis_wheel", glue = (0.0856, -0.0845, 0.014, 0, -1, 0))
    Standard wheel_rear_left(ref = "hiwonder_ackermann_chassis_wheel", glue = (-0.086, 0.0837, 0.014, 0, 1, 0))
    Standard wheel_rear_right(ref = "hiwonder_ackermann_chassis_wheel", glue = (-0.086, -0.0837, 0.014, 0, -1, 0))
}

