// A Hiwonder ClawPi as its Ultimate Kit builds it: the body on four mecanum wheels, with the kit's camera on its
// pan-tilt at the front, its LiDAR on the raised deck and its claw at the front. A Raspberry Pi rides on the
// deck; the kit is sold without one.
Robot clawpi {
    intent "Hiwonder ClawPi mecanum base with its camera, its LiDAR and its claw"

    Mecanum_four_wheel chassis(ref = "hiwonder_clawpi_chassis")

    Mecanum wheel_front_left(ref = "hiwonder_clawpi_mecanum_wheel_fl_rr", glue = (0.0628, 0.0698, -0.0191, 0, 1, 0))
    Mecanum wheel_front_right(ref = "hiwonder_clawpi_mecanum_wheel_fr_rl", glue = (0.0628, -0.0698, -0.0191, 0, -1, 0))
    Mecanum wheel_rear_left(ref = "hiwonder_clawpi_mecanum_wheel_fr_rl", glue = (-0.0714, 0.0698, -0.0191, 0, 1, 0))
    Mecanum wheel_rear_right(ref = "hiwonder_clawpi_mecanum_wheel_fl_rr", glue = (-0.0714, -0.0698, -0.0191, 0, -1, 0))

    Lidar lidar(ref = "hiwonder_clawpi_lidar", glue = (-0.0324, 0, 0.0858, 0, 0, 1))
    Camera camera(ref = "hiwonder_clawpi_camera", glue = (0.0319, 0, 0.0331, 0, 0, 1))
    Attachment claw(ref = "hiwonder_clawpi_claw", glue = (0.0824, 0, -0.0101, 1, 0, 0))
}

