// A Hiwonder JetAcker as its Standard Kit builds it: the body on four 100 mm wheels, the front pair steered and
// the rear pair driven, with the kit's LiDAR in the bay under the upper deck and its depth camera on the pan
// servo. The kit is sold without a computer.
Robot jetacker {
    intent "Hiwonder JetAcker Ackermann base with its LiDAR and depth camera"

    Ackermann chassis(ref = "hiwonder_jetacker_chassis")

    // The kit's motors, each on its seat at a wheel.
    Motor motor_rear_left(ref = "hiwonder_520_gearmotor_90_12v", glue = (-0.105996342, 0.069117841, 0.050334688, 0, 1, 0))
    Motor motor_rear_right(ref = "hiwonder_520_gearmotor_90_12v", glue = (-0.105996342, -0.070142354, 0.050334688, 0, -1, 0))

    Standard wheel_front_left(ref = "hiwonder_rubber_wheel_100mm", glue = (0.1073, 0.1108, 0.05, 0, 1, 0))
    Standard wheel_front_right(ref = "hiwonder_rubber_wheel_100mm", glue = (0.1073, -0.1108, 0.05, 0, -1, 0))
    Standard wheel_rear_left(ref = "hiwonder_rubber_wheel_100mm", glue = (-0.106, 0.1096, 0.0503, 0, 1, 0))
    Standard wheel_rear_right(ref = "hiwonder_rubber_wheel_100mm", glue = (-0.106, -0.1096, 0.0503, 0, -1, 0))

    Lidar lidar(ref = "hiwonder_jetacker_lidar", glue = (0.1041, 0.0007, 0.0862, 0, 0, 1))
    RGBD camera(ref = "hiwonder_jetacker_depth_camera", glue = (0.0313, 0.0007, 0.1616, 0, 0, 1))
}

