// A Hiwonder JetRover as its Standard Kit builds it on the Ackermann chassis: the body on four 100 mm wheels, the
// front pair steered and the rear pair driven, with the kit's LiDAR under the upper deck and its six-axis arm on
// the turntable, holding the depth camera at its wrist. The arm is in the pose the maker's software starts it
// in for mapping, where the camera looks straight ahead. The kit is sold without a computer.
Robot jetrover_acker {
    intent "Hiwonder JetRover Ackermann base with its LiDAR, its arm and the depth camera on the arm"

    Ackermann chassis(ref = "hiwonder_jetrover_acker_chassis")

    // The kit's motors, each on its bracket at a wheel.
    Motor motor_rear_left(ref = "hiwonder_520_gearmotor_90_12v", glue = (-0.106579884, 0.070748952, -0.065486764, 0, 1, 0))
    Motor motor_rear_right(ref = "hiwonder_520_gearmotor_90_12v", glue = (-0.106579884, -0.070901681, -0.065486764, 0, -1, 0))

    Standard wheel_front_left(ref = "hiwonder_rubber_wheel_100mm", glue = (0.1068, 0.1107, -0.0658, 0, 1, 0))
    Standard wheel_front_right(ref = "hiwonder_rubber_wheel_100mm", glue = (0.1068, -0.1107, -0.0658, 0, -1, 0))
    Standard wheel_rear_left(ref = "hiwonder_rubber_wheel_100mm", glue = (-0.1066, 0.1107, -0.0655, 0, 1, 0))
    Standard wheel_rear_right(ref = "hiwonder_rubber_wheel_100mm", glue = (-0.1066, -0.1107, -0.0655, 0, -1, 0))

    Lidar lidar(ref = "hiwonder_jetrover_acker_lidar", glue = (0.09, 0, 0.002, 0, 0, 1))
    Attachment arm(ref = "hiwonder_jetrover_acker_arm", glue = (0.0251, 0, 0.0774, 0, 0, 1))
    RGBD camera(ref = "hiwonder_jetrover_acker_depth_camera", glue = (0.0756, 0, 0.2984, 1, 0, 0))
