// A Hiwonder LanderPi as its Standard Kit builds it on the Ackermann chassis: the body on four 65 mm wheels, the
// front pair steered and the rear pair driven, with the kit's LiDAR at the front of the middle deck and its
// six-axis arm on the turntable, holding the depth camera at its wrist. The arm is in the pose the maker's LiDAR
// app puts it in to drive, where the camera looks ahead and down. A Raspberry Pi 5 rides on the deck; the kit is
// sold without one.
Robot landerpi_acker {
    intent "Hiwonder LanderPi Ackermann base with its LiDAR, its arm and the depth camera on the arm"

    Ackermann chassis(ref = "hiwonder_landerpi_acker_chassis")

    Standard wheel_front_left(ref = "hiwonder_landerpi_acker_front_wheel", glue = (0.0668, 0.0704, -0.0211, 0, 1, 0))
    Standard wheel_front_right(ref = "hiwonder_landerpi_acker_front_wheel", glue = (0.0668, -0.0704, -0.0211, 0, -1, 0))
    Standard wheel_rear_left(ref = "hiwonder_landerpi_acker_rear_wheel", glue = (-0.0677, 0.0704, -0.0211, 0, 1, 0))
    Standard wheel_rear_right(ref = "hiwonder_landerpi_acker_rear_wheel", glue = (-0.0677, -0.0704, -0.0211, 0, -1, 0))

    Lidar lidar(ref = "hiwonder_landerpi_acker_lidar", glue = (0.073, 0, 0.018, 0, 0, 1))
    Attachment arm(ref = "hiwonder_landerpi_acker_arm", glue = (0.0446, 0, 0.0691, 0, 0, 1))
    RGBD camera(ref = "hiwonder_landerpi_acker_depth_camera", glue = (0.0889, 0, 0.2051, 0.7658, 0, -0.6431))
}

