    physics(gravity = (0, 0, -9.81))
    spawn(robot = @core/landerpi_acker, pose = (0, 0, 0.06, 0, 0, 0, 1))
    Scenario room(ref = "empty", ground_plane = true) {
        Obstacle box(
            type = "box", pos = (2.0, 0.6, 0.25, 0, 0, 0, 1), size = (0.4, 0.4, 0.5),
        ),
    }
    Goal goal(pose = (2.5, 0, 0, 0, 0, 0, 1))
}

