// Hiwonder's large metal 4WD chassis as it is sold: the green box with its four motors, on the four mecanum wheels
// it comes with. It is the JetAuto's base; what a robot carries stands on its top plate.
Robot large_4wd {
    intent "Hiwonder large metal 4WD mecanum chassis as it is sold"

    Mecanum_four_wheel chassis(ref = "hiwonder_large_metal_4wd_chassis_green")

    // A mecanum wheel has a hand: the same one goes front-left and rear-right, the other front-right and rear-left.
    // The kit's motors, each on its seat at a wheel.
    Motor motor_front_left(ref = "hiwonder_520_gearmotor_90_12v", glue = (0.097397, 0.070825313, 0.04508, 0, 1, 0))
    Motor motor_front_right(ref = "hiwonder_520_gearmotor_90_12v", glue = (0.097397, -0.070825313, 0.04508, 0, -1, 0))
    Motor motor_rear_left(ref = "hiwonder_520_gearmotor_90_12v", glue = (-0.097397, 0.070089635, 0.04508, 0, 1, 0))
    Motor motor_rear_right(ref = "hiwonder_520_gearmotor_90_12v", glue = (-0.097397, -0.070825313, 0.04508, 0, -1, 0))

    Mecanum wheel_front_left(ref = "hiwonder_mecanum_wheel_97mm_fl_rr", glue = (0.0974, 0.1074, 0.0451, 0, 1, 0))
    Mecanum wheel_front_right(ref = "hiwonder_mecanum_wheel_97mm_fr_rl", glue = (0.0974, -0.1074, 0.0451, 0, -1, 0))
    Mecanum wheel_rear_left(ref = "hiwonder_mecanum_wheel_97mm_fr_rl", glue = (-0.0974, 0.1074, 0.0451, 0, 1, 0))
    Mecanum wheel_rear_right(ref = "hiwonder_mecanum_wheel_97mm_fl_rr", glue = (-0.0974, -0.1074, 0.0451, 0, -1, 0))
}

