// A Hiwonder ROSOrin as its Advanced Kit builds it for Ackermann steering: the body with the kit's steering module
// in place of its front motors, on the kit's four rubber tyres, the front pair steered and the rear pair driven,
// with the kit's LiDAR on the top deck and its depth camera under the deck's front. The kit is sold without a
// computer.
Robot rosorin_acker {
    intent "Hiwonder ROSOrin Ackermann base with its LiDAR and depth camera"

    Ackermann chassis(ref = "hiwonder_rosorin_acker_chassis")

    // The kit's motors, each on its bracket at a wheel.
    Motor motor_rear_left(ref = "hiwonder_520_gearmotor_90_12v", glue = (-0.0808847, 0.0619618, 0.0154721, 0, 1, 0))
    Motor motor_rear_right(ref = "hiwonder_520_gearmotor_90_12v", glue = (-0.0808847, -0.0618128, 0.0154721, 0, -1, 0))

    Standard wheel_front_left(ref = "hiwonder_rosorin_rubber_wheel", glue = (0.0907, 0.086, 0.0155, 0, 1, 0))
