    Standard wheel_rear_left(ref = "hiwonder_rosorin_rubber_wheel", glue = (-0.0808, 0.086, 0.0155, 0, 1, 0))
    Standard wheel_rear_right(ref = "hiwonder_rosorin_rubber_wheel", glue = (-0.0808, -0.086, 0.0155, 0, -1, 0))

