files.core:
// A Pololu 3pi+ 2040 Robot as it is sold, assembled, with the four AAA cells it is sold without: the round body on its
// two 32 mm wheels with the ball moulded under its rear, its control board and removable display on top and its two motors along the axle. The
// cells feed the board, and the board's two channels drive the motors.
Robot pololu_3pi_plus {
    intent "Pololu 3pi+ 2040 Robot, a small round differential-drive robot"

    Diff_two_caster chassis(ref = "pololu_3pi_plus_2040_robot")

    Battery cells(ref = "pololu_3pi_plus_four_nimh_aaa_cells", glue = (0, 0, -0.0085, 0, 0, 1))
    MotorDriver board(ref = "pololu_3pi_plus_2040_control_board", glue = (0, 0, 0.005, 0, 0, 1), power = @core/cells)

    Attachment display(ref = "pololu_3pi_plus_oled_display", glue = (-0.00852, 0, 0.0134, 0, 0, 1))

    Motor motor_left(ref = "pololu_micro_metal_gearmotor_30_mp_6v_extended", glue = (0, 0.038, 0, 0, 1, 0), command = @core/board)
    Motor motor_right(ref = "pololu_micro_metal_gearmotor_30_mp_6v_extended", glue = (0, -0.038, 0, 0, -1, 0), command = @core/board)

    Standard wheel_left(ref = "pololu_wheel_32x7mm_white", glue = (0, 0.0427, 0, 0, 1, 0))
    Standard wheel_right(ref = "pololu_wheel_32x7mm_white", glue = (0, -0.0427, 0, 0, -1, 0))
}

