    intent "Pololu Romi two-wheel differential base with bumper switches across its front"

    Diff_two_caster chassis(ref = "pololu_romi_chassis_kit")

    Battery cells(ref = "pololu_romi_six_nimh_aa_cells", glue = (0, 0, -0.0175, 0, 0, 1))
    MotorDriver board(ref = "pololu_romi_motor_driver_power_board", glue = (0, 0, 0, 0, 0, 1), power = @core/cells)

    Motor motor_left(ref = "pololu_mini_plastic_gearmotor_120_hp_offset_extended", glue = (0, 0.06269, 0, 0, 1, 0), command = @core/board)
    Motor motor_right(ref = "pololu_mini_plastic_gearmotor_120_hp_offset_extended", glue = (0, -0.06269, 0, 0, -1, 0), command = @core/board)

    Standard wheel_left(ref = "pololu_wheel_70x8mm", glue = (0, 0.0704, 0, 0, 1, 0))
    Standard wheel_right(ref = "pololu_wheel_70x8mm", glue = (0, -0.0704, 0, 0, -1, 0))

    Caster caster(ref = "pololu_romi_ball_caster", glue = (-0.064, 0, -0.0223, 0, 0, -1))

