    intent "LEGO Mindstorms NXT Tri-bot with its touch and ultrasonic sensors, a two-wheel differential base that sees what is ahead and feels what it runs into"

    Diff_two_caster chassis(ref = "lego_8527_tribot_chassis")

    Motor motor_left(ref = "lego_nxt_motor", glue = (0, 0.0315, 0, -0.04, 0, -0.9992))
