    Standard wheel_left(ref = "lego_8527_tribot_wheel", glue = (0, 0.056, 0, 0, 1, 0))
    Standard wheel_right(ref = "lego_8527_tribot_wheel", glue = (0, -0.056, 0, 0, -1, 0))

    Bumper touch(ref = "lego_8527_touch_sensor", glue = (0.037008, -0.000515, 0.023531, 1, 0, 0))
    Ultrasonic sonar(ref = "lego_8527_ultrasonic_sensor", glue = (0.086175, -0.000515, 0.061965, 1, 0, 0))
}

